# ---------------------------------------------------------------- 01 了
quiz("01_le", "zh-a2-le", "The Many Faces of 了",
     "Completed actions, new situations, 'not anymore', 快…了, 已经…了, durations with one or two 了, and 了吗 questions.",
     [P("le_done", "Verb + 了 + object: completed action", "了 right after the verb marks a completed action. A quantified object (三杯, 一本) usually follows.",
        "- 他喝**了**三杯咖啡.\n- 我买**了**一本书.\n- Negative: 没 + verb, **without** 了 (我没买书).",
        [("他/tā 喝/hē 了/le 三/sān 杯/bēi 咖啡/kāfēi 。", "He drank three cups of coffee.")]),
      P("le_change", "Sentence + 了: change / new situation", "了 at the end of a sentence says 'now it's like this' — something has changed.",
        "- 下雨**了**! (It's started raining!)\n- 我饿**了** (I'm hungry now).\n- 不 + verb + 了 = not anymore: 我不喝酒**了**.",
        [("我/wǒ 不/bù 喝/hē 酒/jiǔ 了/le 。", "I don't drink anymore.")]),
      P("kuaile", "快(要) + verb + 了: about to", "快 / 快要 + verb/adj + 了 = something is about to happen. The 了 is required.",
        "- 火车**快要**开**了**.\n- 我们**快**到北京**了**.",
        [("我们/wǒmen 快/kuài 到/dào 北京/Běijīng 了/le 。", "We're almost in Beijing.")]),
      P("yijing", "已经…了: already", "已经 (yǐjīng) + verb … + 了 = already.",
        "- 我**已经**吃过饭**了**.\n- 他**已经**走**了**.",
        [("他/tā 已经/yǐjīng 走/zǒu 了/le 。", "He's already left.")]),
      P("le_duration", "Verb + 了 + duration (+ 了)", "One 了: the action lasted that long (finished). Two 了: it has lasted that long **so far** and is still going.",
        "- 我学**了**两年中文 (I studied for two years — maybe I've stopped).\n- 我学**了**两年中文**了** (I've been studying for two years — and still am).",
        [("我/wǒ 学/xué 了/le 两/liǎng 年/nián 中文/Zhōngwén 了/le 。", "I've been learning Chinese for two years now.")]),
      P("lema", "Verb + 了吗? / 还没(有)", "Did you …? = verb + 了吗? Answer: verb + 了 / 还没(有) (not yet).",
        "- 你吃饭**了吗**? — 吃了 / 还没有.",
        [("你/nǐ 吃饭/chīfàn 了/le 吗/ma ？", "Have you eaten?")])],
     [Q("le_done", zh("我/wǒ 昨天/zuótiān 买/mǎi （　） 一/yì 本/běn 书/shū ， 今天/jīntiān 已经/yǐjīng 看/kàn 完/wán 了/le 。"), ["了/le", "着/zhe", "的/de", "在/zài"],
        ["", "着 marks a lasting state, not a finished purchase.", "买的一本书 would need a noun after it in a different structure.", "在 goes before the verb."],
        "Completed action: **verb + 了**.", "I bought a book yesterday and finished reading it today."),
      Q("le_done", "Which sentence is correct?", ["他/tā 喝/hē 了/le 三/sān 杯/bēi 咖啡/kāfēi 。", "他/tā 了/le 喝/hē 三/sān 杯/bēi 咖啡/kāfēi 。", "他/tā 喝/hē 三/sān 了/le 杯/bēi 咖啡/kāfēi 。", "他/tā 喝/hē 三/sān 杯/bēi 了/le 咖啡/kāfēi 。"],
        ["", "了 comes after the verb, not before it.", "了 can't split the number and the measure word.", "了 can't split the measure word and the noun."],
        "Verb + **了** + quantity + noun.", "He drank three cups of coffee."),
      Q("le_change", zh("下雨/xià yǔ （　） ！ 我们/wǒmen 快/kuài 回家/huíjiā 吧/ba 。"), ["了/le", "过/guo", "着/zhe", "的/de"],
        ["", "下雨过 = 'it has rained before' — not a new situation.", "下雨着 isn't natural.", "的 doesn't mark a change."],
        "New situation: sentence + **了**.", "It's started raining! Let's hurry home."),
      Q("le_change", "What does 「" + zh("我/wǒ 不/bù 喝/hē 酒/jiǔ 了/le 。") + "」 mean?", ["I don't drink anymore.", "I didn't drink.", "I'm not drinking yet.", "I've never drunk."],
        ["", "That's 我没喝酒.", "That's 我还没喝.", "That's 我从来没喝过酒."],
        "不…**了** = not anymore.", ""),
      Q("kuaile", zh("火车/huǒchē （　） 开/kāi 了/le ， 你/nǐ 快/kuài 上车/shàngchē 吧/ba ！"), ["快要/kuàiyào", "已经/yǐjīng", "刚/gāng", "正在/zhèngzài"],
        ["", "If it had already left, you couldn't get on.", "刚开了 isn't the pattern — and you couldn't get on either.", "正在 doesn't combine with 了 like this."],
        "About to: **快要…了**.", "The train is about to leave — get on quickly!"),
      Q("kuaile", "Which sentence is correct?", ["我们/wǒmen 快/kuài 到/dào 北京/Běijīng 了/le 。", "我们/wǒmen 快/kuài 到/dào 北京/Běijīng 。", "我们/wǒmen 到/dào 北京/Běijīng 快/kuài 了/le 。", "我们/wǒmen 快/kuài 了/le 到/dào 北京/Běijīng 。"],
        ["", "快 needs the final 了.", "快 goes before the verb.", "了 goes at the end."],
        "**快 + verb + 了**.", "We're almost in Beijing."),
      Q("yijing", zh("我/wǒ （　） 吃/chī 过/guo 饭/fàn 了/le ， 不/bú 饿/è 。"), ["已经/yǐjīng", "还/hái", "正在/zhèngzài", "快/kuài"],
        ["", "还吃过饭了 isn't grammatical.", "正在 = 'in the middle of' — clashes with 过…了.", "快吃过饭了 isn't grammatical."],
        "Already: **已经…了**.", "I've already eaten, I'm not hungry."),
      Q("yijing", zh("他/tā （　） 走/zǒu 了/le ， 你/nǐ 明天/míngtiān 再/zài 来/lái 吧/ba 。"), ["已经/yǐjīng", "一直/yìzhí", "正在/zhèngzài", "从来/cónglái"],
        ["", "一直走 = 'go straight / keep walking'.", "正在走了 isn't grammatical.", "从来 needs a negative."],
        "**已经…了**.", "He's already left — come back tomorrow."),
      Q("le_duration", zh("我/wǒ 学/xué （　） 两/liǎng 年/nián 中文/Zhōngwén ， 现在/xiànzài 能/néng 看/kàn 懂/dǒng 一点儿/yìdiǎnr 。"), ["了/le", "着/zhe", "在/zài", "的/de"],
        ["", "着 doesn't take a duration like this.", "在 goes before the verb.", "学的两年 isn't the pattern."],
        "Duration: **verb + 了 + time**.", "I studied Chinese for two years and can now understand a little."),
      Q("le_duration", "Which sentence says you are **still** learning (two years so far)?", ["我/wǒ 学/xué 了/le 两/liǎng 年/nián 中文/Zhōngwén 了/le 。", "我/wǒ 学/xué 了/le 两/liǎng 年/nián 中文/Zhōngwén 。", "我/wǒ 学/xué 过/guo 两/liǎng 年/nián 中文/Zhōngwén 。", "我/wǒ 两/liǎng 年/nián 学/xué 中文/Zhōngwén 。"],
        ["", "One 了 = it lasted two years (could be over).", "过 = at some point in the past.", "The duration goes after the verb."],
        "Ongoing: **了 + duration + 了**.", "I've been learning Chinese for two years now."),
      Q("lema", zh("A： 你/nǐ 吃饭/chīfàn （　） ？ // B： 吃/chī 了/le 。"), ["了/le 吗/ma", "吗/ma 了/le", "过/guo 了/le", "了/le 呢/ne"],
        ["", "The order is 了吗.", "过了 doesn't make a question.", "了呢 doesn't ask a yes/no question."],
        "Did you …?: **了吗**.", "A: Have you eaten? B: Yes."),
      Q("lema", zh("A： 你/nǐ 买/mǎi 票/piào 了/le 吗/ma ？ // B： 还/hái （　） 。"), ["没有/méiyǒu", "不/bù", "没有了/méiyǒu le", "不了/bù le"],
        ["", "还不 doesn't answer 'did you?'.", "No 了 after 还没有.", "还不了 isn't an answer."],
        "Not yet: **还没(有)**.", "A: Have you bought the tickets? B: Not yet.")])

# ---------------------------------------------------------------- 02 aspect & time adverbs
quiz("02_aspect", "zh-a2-aspect", "Experience & Progress: 过, 正在, 一直, 刚 / 刚才, 从来",
     "Have you ever (过), in the middle of (正在…呢), all along (一直), just (刚 vs 刚才) and never (从来不 / 从来没).",
     [P("guo", "Verb + 过: have (ever) done", "过 (guo) marks an experience — something you've done at least once. Negative: 没 + verb + 过.",
        "- 我吃**过**饺子 (I've had dumplings before).\n- 我没去**过**上海 (I've never been to Shanghai).\n- 了 = a specific finished event; 过 = 'ever'.",
        [("我/wǒ 没/méi 去/qù 过/guo 上海/Shànghǎi 。", "I've never been to Shanghai.")]),
      P("zhengzai", "(正)在 + verb (+ 呢): in progress", "正在 / 在 + verb = be doing right now. 呢 at the end is common.",
        "- 我**正在**做饭**呢**.\n- 他们**在**开会.",
        [("我/wǒ 正在/zhèngzài 做饭/zuòfàn 呢/ne 。", "I'm cooking right now.")]),
      P("yizhi", "一直: all along, continuously", "一直 (yìzhí) + verb = has been / kept doing all along.",
        "- 雨**一直**下了三天.\n- 我**一直**想去中国.",
        [("我/wǒ 一直/yìzhí 想/xiǎng 去/qù 中国/Zhōngguó 。", "I've always wanted to go to China.")]),
      P("gang", "刚 vs 刚才: just / just now", "刚 (gāng) is an adverb: subject + 刚 + verb, can take a duration (刚来了一个月). 刚才 (gāngcái) is a time noun = a moment ago; it can start the sentence and go with 没/不.",
        "- 我**刚**到家.\n- **刚才**你去哪儿了?\n- 他**刚**来了一个月 — not ~~刚才来了一个月~~.",
        [("刚才/gāngcái 你/nǐ 去/qù 哪儿/nǎr 了/le ？", "Where did you go just now?")]),
      P("conglai", "从来 + 不 / 没(有): never", "从来不 = never (habit / principle). 从来没(有) + verb + 过 = have never (experience).",
        "- 他**从来不**喝酒.\n- 我**从来没**吃**过**北京烤鸭.",
        [("他/tā 从来/cónglái 不/bù 喝/hē 酒/jiǔ 。", "He never drinks.")])],
     [Q("guo", "What does 「" + zh("我/wǒ 吃/chī 过/guo 饺子/jiǎozi 。") + "」 mean?", ["I've had dumplings before.", "I'm eating dumplings.", "I've just eaten dumplings.", "I ate too many dumplings."],
        ["", "That's 我在吃饺子.", "That's 我刚吃了饺子.", "That's 吃得太多了."],
        "过 = **experience**.", ""),
      Q("guo", "Which sentence is correct?", ["我/wǒ 没/méi 去/qù 过/guo 上海/Shànghǎi 。", "我/wǒ 没/méi 去/qù 了/le 上海/Shànghǎi 。", "我/wǒ 不/bú 去/qù 过/guo 上海/Shànghǎi 。", "我/wǒ 没/méi 去/qù 上海/Shànghǎi 过/guo 。"],
        ["", "No 了 after 没.", "Experience is negated with 没, not 不.", "过 goes right after the verb."],
        "**没 + verb + 过**.", "I've never been to Shanghai."),
      Q("zhengzai", zh("A： 你/nǐ 在/zài 做/zuò 什么/shénme ？ // B： 我/wǒ （　） 做饭/zuòfàn 呢/ne 。"), ["正在/zhèngzài", "已经/yǐjīng", "刚/gāng", "就/jiù"],
        ["", "已经做饭呢 doesn't fit — 已经 needs 了.", "刚做饭呢 isn't natural.", "就 doesn't express 'in progress'."],
        "In progress: **正在…呢**.", "A: What are you doing? B: I'm cooking."),
      Q("zhengzai", zh("别/bié 进去/jìnqù ， 他们/tāmen 正在/zhèngzài 开会/kāihuì （　） 。"), ["呢/ne", "了/le", "过/guo", "吗/ma"],
        ["", "正在…了 isn't the pattern.", "正在 and 过 don't go together.", "吗 makes a question."],
        "**正在…呢**.", "Don't go in — they're in a meeting."),
      Q("yizhi", zh("雨/yǔ （　） 下/xià 了/le 三/sān 天/tiān ， 还/hái 没/méi 停/tíng 。"), ["一直/yìzhí", "刚/gāng", "从来/cónglái", "正在/zhèngzài"],
        ["", "刚 + three days of rain doesn't fit 还没停.", "从来 needs a negative.", "正在 doesn't combine with 了 + duration."],
        "All along: **一直**.", "It's been raining for three days without stopping."),
      Q("yizhi", zh("我/wǒ （　） 想/xiǎng 去/qù 中国/Zhōngguó 留学/liúxué ， 明年/míngnián 终于/zhōngyú 可以/kěyǐ 去/qù 了/le 。"), ["一直/yìzhí", "刚/gāng", "刚才/gāngcái", "马上/mǎshàng"],
        ["", "刚想 = 'just thought of'.", "刚才 = 'a moment ago'.", "马上 = 'right away'."],
        "Always (wanted): **一直**.", "I've always wanted to study in China — next year I finally can."),
      Q("gang", zh("（　） 你/nǐ 去/qù 哪儿/nǎr 了/le ？ 我/wǒ 找/zhǎo 了/le 你/nǐ 半天/bàntiān 。"), ["刚才/gāngcái", "刚/gāng", "已经/yǐjīng", "一直/yìzhí"],
        ["", "刚 is an adverb — it can't start the sentence.", "已经 can't start the sentence like this.", "一直 can't start the sentence like this."],
        "A moment ago (sentence start): **刚才**.", "Where did you go just now? I've been looking for you for ages."),
      Q("gang", zh("他/tā （　） 来/lái 了/le 一个/yí ge 月/yuè ， 还/hái 不/bú 太/tài 习惯/xíguàn 。"), ["刚/gāng", "刚才/gāngcái", "一直/yìzhí", "从来/cónglái"],
        ["", "刚才 can't go with a duration like 一个月.", "一直来了 isn't grammatical.", "从来 needs a negative."],
        "Just (+ duration): **刚**.", "He came only a month ago and isn't used to it yet."),
      Q("conglai", zh("我/wǒ 从来/cónglái 没/méi 吃/chī （　） 北京/Běijīng 烤鸭/kǎoyā 。"), ["过/guo", "了/le", "着/zhe", "在/zài"],
        ["", "No 了 after 没.", "着 doesn't fit.", "在 goes before the verb."],
        "Never (experience): **从来没…过**.", "I've never had Peking duck."),
      Q("conglai", zh("他/tā （　） 不/bù 喝/hē 酒/jiǔ ， 也/yě 不/bù 抽烟/chōuyān 。"), ["从来/cónglái", "已经/yǐjīng", "刚/gāng", "正在/zhèngzài"],
        ["", "已经不 would need 了 at the end.", "刚不 isn't grammatical.", "正在不 isn't grammatical."],
        "Never (habit): **从来不**.", "He never drinks or smokes.")])

# ---------------------------------------------------------------- 03 comparisons
quiz("03_comparisons", "zh-a2-comparisons", "Comparisons: 比, 没有, 跟…一样, 更, 最, 多, 有点儿",
     "A 比 B + adj (and why 很 can't go there), 没有 for 'not as … as', sameness with 一样, how tall/far with 多, and 有点儿 vs 一点儿.",
     [P("bi", "A 比 B + adjective", "A 比 B + adj = A is more … than B. No 很 / 非常 / 太 before the adjective — use 更 / 还, or put the amount after it.",
        "- 哥哥**比**我高.\n- 他**比**我高**一点儿** / 高**两厘米**.\n- 今天**比**昨天**更**冷.\n- ~~他比我很高~~ ✗",
        [("今天/jīntiān 比/bǐ 昨天/zuótiān 更/gèng 冷/lěng 。", "Today is even colder than yesterday.")]),
      P("meiyou_comp", "A 没有 B + adjective: not as … as", "A 没有 B (那么) + adj = A isn't as … as B.",
        "- 我**没有**他高 (I'm not as tall as him).\n- 不比 = 'not more … than' (maybe equal) — weaker.",
        [("我/wǒ 没有/méiyǒu 他/tā 高/gāo 。", "I'm not as tall as him.")]),
      P("yiyang", "A 跟 / 和 B 一样 (+ adj)", "A 跟 B 一样 = A is the same as B; 一样 + adj = equally ….",
        "- 我的手机**跟**你的**一样**.\n- 我**跟**他**一样**高.",
        [("我/wǒ 跟/gēn 他/tā 一样/yíyàng 高/gāo 。", "I'm as tall as him.")]),
      P("zui", "最 + adjective: the most", "最 (zuì) = most / -est.",
        "- 他是我们班**最**高的学生.",
        [("这/zhè 是/shì 我/wǒ 最/zuì 喜欢/xǐhuan 的/de 菜/cài 。", "This is my favourite dish.")]),
      P("duo", "多 + adjective?: how …?", "(有) 多 + adj? asks for an amount: 多高 (how tall), 多远, 多大 (how old), 多长.",
        "- 你**多**高? — 一米八.\n- 长城有**多**长?",
        [("你/nǐ 多/duō 高/gāo ？", "How tall are you?")]),
      P("youdian", "有点儿 vs 一点儿", "有点儿 + adj = a bit (too) …, usually negative, **before** the adjective. Adj + 一点儿 = a bit more …, **after** the adjective (comparisons, requests).",
        "- 今天**有点儿**冷.\n- 便宜**一点儿**吧! / 有没有大**一点儿**的?",
        [("今天/jīntiān 有点儿/yǒudiǎnr 冷/lěng 。", "It's a bit cold today.")])],
     [Q("bi", zh("哥哥/gēge （　） 我/wǒ 高/gāo 。"), ["比/bǐ", "跟/gēn", "和/hé", "对/duì"],
        ["", "跟我高 isn't a comparison — 跟 needs 一样.", "和我高 isn't grammatical.", "对 = 'towards'."],
        "Comparison: **比**.", "My older brother is taller than me."),
      Q("bi", "Which sentence is correct?", ["他/tā 比/bǐ 我/wǒ 高/gāo 一点儿/yìdiǎnr 。", "他/tā 比/bǐ 我/wǒ 很/hěn 高/gāo 。", "他/tā 比/bǐ 我/wǒ 高/gāo 很/hěn 。", "他/tā 很/hěn 比/bǐ 我/wǒ 高/gāo 。"],
        ["", "No 很 in a 比 comparison.", "很 can't go after the adjective.", "很 can't go before 比."],
        "比 + adj (+ amount).", "He's a bit taller than me."),
      Q("bi", zh("今天/jīntiān 比/bǐ 昨天/zuótiān （　） 冷/lěng 。"), ["更/gèng", "很/hěn", "非常/fēicháng", "太/tài"],
        ["", "很 can't be used with 比.", "非常 can't be used with 比.", "太 can't be used with 比."],
        "Even more: **比…更**.", "Today is even colder than yesterday."),
      Q("meiyou_comp", "Which sentence means 'I'm not as tall as him'?", ["我/wǒ 没有/méiyǒu 他/tā 高/gāo 。", "我/wǒ 不/bù 比/bǐ 他/tā 高/gāo 。", "他/tā 没有/méiyǒu 我/wǒ 高/gāo 。", "我/wǒ 比/bǐ 他/tā 不/bù 高/gāo 。"],
        ["", "不比 = 'not taller than' — we might be the same height.", "That's 'he's not as tall as me'.", "不 can't go after 比."],
        "**A 没有 B + adj**.", "I'm not as tall as him."),
      Q("meiyou_comp", zh("北京/Běijīng 的/de 冬天/dōngtiān （　） 哈尔滨/Hā'ěrbīn 冷/lěng 。"), ["没有/méiyǒu", "不有/bù yǒu", "不是/búshì", "不要/búyào"],
        ["", "不有 doesn't exist.", "不是 doesn't make comparisons.", "不要 = 'don't'."],
        "Not as … as: **没有**.", "Winter in Beijing isn't as cold as in Harbin."),
      Q("yiyang", zh("我/wǒ 的/de 手机/shǒujī 跟/gēn 你/nǐ 的/de （　） 。"), ["一样/yíyàng", "一起/yìqǐ", "一下/yíxià", "一点/yìdiǎn"],
        ["", "一起 = 'together'.", "一下 = 'briefly'.", "一点 = 'a little'."],
        "Same: **跟…一样**.", "My phone is the same as yours."),
      Q("yiyang", "Which sentence is correct?", ["我/wǒ 跟/gēn 他/tā 一样/yíyàng 高/gāo 。", "我/wǒ 跟/gēn 他/tā 高/gāo 一样/yíyàng 。", "我/wǒ 一样/yíyàng 跟/gēn 他/tā 高/gāo 。", "我/wǒ 跟/gēn 他/tā 一样/yíyàng 很/hěn 高/gāo 。"],
        ["", "一样 goes before the adjective.", "跟 + B comes first.", "No 很 after 一样."],
        "A 跟 B **一样** + adj.", "I'm as tall as him."),
      Q("zui", zh("他/tā 是/shì 我们/wǒmen 班/bān （　） 高/gāo 的/de 学生/xuésheng 。"), ["最/zuì", "更/gèng", "太/tài", "比/bǐ"],
        ["", "更 compares two things.", "太高的学生 = 'too tall a student'.", "比 needs a second noun."],
        "The most: **最**.", "He's the tallest student in our class."),
      Q("zui", zh("这/zhè 是/shì 我/wǒ （　） 喜欢/xǐhuan 的/de 菜/cài 。"), ["最/zuì", "更/gèng", "太/tài", "比/bǐ"],
        ["", "更 needs something to compare with.", "太喜欢的 isn't natural.", "比 needs a second noun."],
        "Favourite: **最喜欢**.", "This is my favourite dish."),
      Q("duo", zh("A： 你/nǐ （　） 高/gāo ？ // B： 一/yì 米/mǐ 八/bā 。"), ["多/duō", "几/jǐ", "怎么/zěnme", "什么/shénme"],
        ["", "几高 isn't grammatical.", "怎么高 = 'how come (you're) tall'.", "什么高 isn't grammatical."],
        "How + adj: **多**.", "A: How tall are you? B: 1.80 m."),
      Q("duo", zh("长城/Chángchéng 有/yǒu （　） 长/cháng ？"), ["多/duō", "几/jǐ", "哪/nǎ", "怎么/zěnme"],
        ["", "几长 isn't grammatical.", "哪长 isn't grammatical.", "怎么长 = 'how does it grow'."],
        "**有多 + adj**?", "How long is the Great Wall?"),
      Q("youdian", zh("今天/jīntiān （　） 冷/lěng ， 多/duō 穿/chuān 点儿/diǎnr 衣服/yīfu 。"), ["有点儿/yǒudiǎnr", "一点儿/yìdiǎnr", "一些/yìxiē", "有的/yǒude"],
        ["", "一点儿 goes after the adjective, not before.", "一些 goes before nouns.", "有的 = 'some (of them)'."],
        "A bit (unpleasant): **有点儿 + adj**.", "It's a bit cold today — put on some more clothes."),
      Q("youdian", zh("这/zhè 件/jiàn 太/tài 贵/guì 了/le ， 有/yǒu 没有/méiyǒu 便宜/piányi （　） 的/de ？"), ["一点儿/yìdiǎnr", "有点儿/yǒudiǎnr", "一些儿/yìxiēr", "有的/yǒude"],
        ["", "有点儿 goes before the adjective.", "一些儿 isn't a word.", "有的 = 'some'."],
        "A bit more …: **adj + 一点儿**.", "This one is too expensive — do you have a slightly cheaper one?")])

# ---------------------------------------------------------------- 04 adverbs
quiz("04_adverbs", "zh-a2-adverbs", "Small Adverbs: 就, 还, 只, 总是, 别, 一边…一边, 又…又",
     "Early/right away (就), also/OK-ish (还), only (只), always (总是), don't/stop (别…了), doing two things at once and 'both … and'.",
     [P("jiu", "就: (as early as) / right away", "就 (jiù) + verb: earlier/sooner than expected, or 'right away'. Often with 了.",
        "- 他六点**就**起床了 (He got up as early as six).\n- 我马上**就**来.",
        [("我/wǒ 马上/mǎshàng 就/jiù 来/lái 。", "I'll be right there.")]),
      P("hai", "还: also; (it's) OK", "还 + verb = in addition (还买了…). 还 + adj = reasonably, OK-ish: 还可以, 还不错.",
        "- 我买了苹果，**还**买了香蕉.\n- 这个电影**还**可以 (It's OK).",
        [("这个/zhège 电影/diànyǐng 还/hái 可以/kěyǐ 。", "This film is OK.")]),
      P("zhi", "只 + verb: only", "只 (zhǐ) goes **before the verb**, even when 'only' refers to the object.",
        "- 我**只**会说一点儿中文.\n- 我**只**有一百块钱.",
        [("我/wǒ 只/zhǐ 有/yǒu 一百/yìbǎi 块/kuài 钱/qián 。", "I only have 100 yuan.")]),
      P("zongshi", "总是 + verb: always", "总是 (zǒngshì) = always, every time (habit, often annoying).",
        "- 他**总是**迟到.",
        [("他/tā 总是/zǒngshì 迟到/chídào 。", "He's always late.")]),
      P("bie", "别 + verb (+ 了): don't / stop", "别 (bié) + verb = don't. 别 + verb + 了 = stop doing it (it's happening now).",
        "- **别**担心.\n- **别**说话**了**! (Stop talking!)",
        [("别/bié 说话/shuōhuà 了/le ！", "Stop talking!")]),
      P("yibian", "一边 A 一边 B: doing A while B", "一边 + verb 1，一边 + verb 2 = doing both at the same time.",
        "- 他**一边**吃饭，**一边**看电视.",
        [("我们/wǒmen 一边/yìbiān 走/zǒu 一边/yìbiān 聊天/liáotiān 。", "We chatted as we walked.")]),
      P("youyou", "又 A 又 B: both A and B", "又 + adj/verb，又 + adj/verb = both … and … (same direction: both good or both bad).",
        "- 这个苹果**又**大**又**甜.",
        [("他/tā 又/yòu 高/gāo 又/yòu 帅/shuài 。", "He's both tall and handsome.")])],
     [Q("jiu", zh("他/tā 早上/zǎoshang 六/liù 点/diǎn （　） 起床/qǐchuáng 了/le 。"), ["就/jiù", "才/cái", "还/hái", "都/dōu"],
        ["", "才 = 'not until' — and it doesn't take 了.", "还起床了 isn't grammatical.", "都 needs a plural subject."],
        "As early as: **就…了**.", "He got up as early as six this morning."),
      Q("jiu", zh("你/nǐ 等/děng 一下/yíxià ， 我/wǒ 马上/mǎshàng （　） 来/lái 。"), ["就/jiù", "才/cái", "还/hái", "只/zhǐ"],
        ["", "马上才 is contradictory.", "还来 = 'still coming / coming again'.", "只来 = 'only coming'."],
        "Right away: **马上就**.", "Wait a moment, I'll be right there."),
      Q("hai", zh("我/wǒ 买/mǎi 了/le 苹果/píngguǒ ， （　） 买/mǎi 了/le 香蕉/xiāngjiāo 。"), ["还/hái", "都/dōu", "就/jiù", "只/zhǐ"],
        ["", "都 needs a plural subject.", "就 = 'right away / as early as'.", "只 = 'only' — contradicts buying apples too."],
        "In addition: **还**.", "I bought apples, and bananas too."),
      Q("hai", "What does 「" + zh("这个/zhège 电影/diànyǐng 还/hái 可以/kěyǐ 。") + "」 mean?", ["This film is OK / not bad.", "This film is still showing.", "This film is excellent.", "This film is also allowed."],
        ["", "That would be 还在上映.", "还可以 is lukewarm, not enthusiastic.", "还 + adj here means 'reasonably'."],
        "还 + adj = **reasonably, OK**.", ""),
      pos("zhi", "只/zhǐ", "我/wǒ @A 会/huì @B 说/shuō @C 一点儿/yìdiǎnr @D 中文/Zhōngwén 。", 0,
          ["", "只 goes before the first verb (会).", "只 can't split 说 and its object.", "只 can't go inside the object."],
          "**只** before the verb phrase.", "I can only speak a little Chinese."),
      Q("zhi", zh("我/wǒ （　） 有/yǒu 一百/yìbǎi 块/kuài 钱/qián ， 不/bú 够/gòu 买/mǎi 这个/zhège 。"), ["只/zhǐ", "都/dōu", "也/yě", "又/yòu"],
        ["", "都 needs a plural subject.", "也 = 'also'.", "又 = 'again'."],
        "Only: **只**.", "I only have 100 yuan — not enough to buy this."),
      Q("zongshi", zh("他/tā （　） 迟到/chídào ， 老师/lǎoshī 很/hěn 生气/shēngqì 。"), ["总是/zǒngshì", "已经/yǐjīng", "从来/cónglái", "刚/gāng"],
        ["", "已经 needs 了.", "从来 needs a negative.", "刚迟到 doesn't explain an angry teacher well."],
        "Always: **总是**.", "He's always late, and the teacher is angry."),
      Q("zongshi", zh("我/wǒ 妈妈/māma （　） 说/shuō 我/wǒ 太/tài 瘦/shòu 了/le 。"), ["总是/zǒngshì", "从来/cónglái", "已经/yǐjīng", "快/kuài"],
        ["", "从来 needs a negative.", "已经说 doesn't fit a repeated comment.", "快说 = 'say it quickly!'."],
        "Always: **总是**.", "My mum always says I'm too thin."),
      Q("bie", zh("（　） 说话/shuōhuà 了/le ， 电影/diànyǐng 开始/kāishǐ 了/le ！"), ["别/bié", "没/méi", "没有/méiyǒu", "不是/búshì"],
        ["", "没说话了 isn't grammatical.", "没有说话了 isn't grammatical.", "不是 negates nouns."],
        "Stop doing: **别…了**.", "Stop talking, the film has started!"),
      Q("bie", zh("外面/wàimiàn 很/hěn 冷/lěng ， 你/nǐ （　） 出去/chūqù 了/le 。"), ["别/bié", "没/méi", "没有/méiyǒu", "不是/búshì"],
        ["", "你没出去了 isn't grammatical.", "没有出去了 isn't grammatical.", "不是出去 doesn't fit."],
        "Don't (anymore): **别…了**.", "It's cold outside — don't go out."),
      Q("yibian", zh("他/tā 一边/yìbiān 吃饭/chīfàn ， （　） 看/kàn 电视/diànshì 。"), ["一边/yìbiān", "一起/yìqǐ", "一样/yíyàng", "一点/yìdiǎn"],
        ["", "一起 = 'together'.", "一样 = 'the same'.", "一点 = 'a little'."],
        "**一边…一边**.", "He watches TV while eating."),
      Q("yibian", "Which sentence is correct?", ["我们/wǒmen 一边/yìbiān 走/zǒu 一边/yìbiān 聊天/liáotiān 。", "我们/wǒmen 一边/yìbiān 走/zǒu 一起/yìqǐ 聊天/liáotiān 。", "一边/yìbiān 我们/wǒmen 走/zǒu 一边/yìbiān 聊天/liáotiān 。", "我们/wǒmen 走/zǒu 一边/yìbiān 聊天/liáotiān 一边/yìbiān 。"],
        ["", "The pair is 一边…一边.", "The subject comes first.", "一边 goes before each verb."],
        "Subject + **一边** V1 **一边** V2.", "We chatted as we walked."),
      Q("youyou", zh("这个/zhège 苹果/píngguǒ 又/yòu 大/dà （　） 甜/tián 。"), ["又/yòu", "也/yě", "还/hái", "和/hé"],
        ["", "The pattern repeats 又.", "The pattern repeats 又.", "和 doesn't link adjectives."],
        "**又…又**.", "This apple is big and sweet."),
      Q("youyou", "Which sentence is correct?", ["他/tā 又/yòu 高/gāo 又/yòu 帅/shuài 。", "他/tā 又/yòu 高/gāo 和/hé 帅/shuài 。", "他/tā 很/hěn 高/gāo 又/yòu 很/hěn 帅/shuài 又/yòu 。", "他/tā 又/yòu 高/gāo 很/hěn 帅/shuài 。"],
        ["", "和 can't link adjectives.", "又 goes before each adjective.", "The second 又 is missing."],
        "**又 + adj，又 + adj**.", "He's both tall and handsome.")])

# ---------------------------------------------------------------- 05 complements
quiz("05_complements", "zh-a2-complements", "的 / 得 / 地 and Result Complements: 完, 到, 见, 懂, 好 / 难 + verb",
     "The three 'de', how well something is done (V得…), finished (完), managed / perceived (到, 见), understood (懂), and easy / hard to do.",
     [P("de3", "的 vs 得 vs 地", "All three sound 'de'. 的 links to a **noun** (my book, the clothes I bought). 得 follows a **verb** to say how well/how much (跑得快). 地 turns an adjective into an **adverb before a verb** (高兴地说).",
        "- 我昨天买**的**衣服.\n- 他跑**得**很快.\n- 她高兴**地**说.",
        [("他/tā 跑/pǎo 得/de 很/hěn 快/kuài 。", "He runs fast.")]),
      P("degree", "Verb + 得 + adj: how well", "Verb + 得 + (很) adj. With an object, repeat the verb: 他说中文**说得**很好 (or 他中文说得很好). Negative: verb + 得 + 不 + adj.",
        "- 他说中文说**得很好**.\n- 他跑**得不快** — not ~~不跑得快~~.",
        [("他/tā 说/shuō 中文/Zhōngwén 说/shuō 得/de 很/hěn 好/hǎo 。", "He speaks Chinese very well.")]),
      P("wan", "Verb + 完: finish", "完 (wán) after a verb = finish doing it.",
        "- 我做**完**作业了.\n- 我看**完**了这本书.",
        [("我/wǒ 已经/yǐjīng 做/zuò 完/wán 作业/zuòyè 了/le 。", "I've already finished my homework.")]),
      P("daojian", "Verb + 到 / 见: manage to, perceive", "到 = reach the goal (找到 find, 买到 manage to buy). 见 = perceive (看见 see, 听见 hear).",
        "- 我找**到**钥匙了.\n- 你听**见**了吗?",
        [("我/wǒ 找/zhǎo 到/dào 我/wǒ 的/de 钥匙/yàoshi 了/le 。", "I found my keys.")]),
      P("budong", "Verb + 不懂 / 懂: (not) understand", "看懂 / 听懂 = understand by reading/listening. Can't: 看**不**懂 / 听**不**懂. 听不见 = can't hear (too quiet), 听不懂 = can't understand.",
        "- 老师说得太快，我听**不懂**.\n- 这本书我看**不懂**.",
        [("这/zhè 本/běn 书/shū 我/wǒ 看/kàn 不/bu 懂/dǒng 。", "I can't understand this book.")]),
      P("haonan", "好 / 难 + verb: easy / hard to …", "好 + verb = easy to … / nice to … (好吃, 好写). 难 + verb = hard to … / bad to … (难吃, 难写).",
        "- 这个字很**难**写.\n- 饺子很**好**吃.",
        [("这个/zhège 字/zì 很/hěn 难/nán 写/xiě 。", "This character is hard to write.")])],
     [Q("de3", zh("他/tā 跑/pǎo （　） 很/hěn 快/kuài 。"), ["得/de", "的/de", "地/de", "了/le"],
        ["", "的 links to a noun.", "地 comes before a verb.", "跑了很快 isn't grammatical."],
        "Verb + **得** + how.", "He runs fast."),
      Q("de3", zh("她/tā 高兴/gāoxìng （　） 说/shuō ： “ 太/tài 好/hǎo 了/le ！ ”"), ["地/de", "的/de", "得/de", "了/le"],
        ["", "的 links to a noun, not a verb.", "得 comes after a verb, not before one.", "高兴了说 isn't grammatical."],
        "Adverb before a verb: **地**.", "She said happily: 'Great!'"),
      Q("de3", zh("这/zhè 是/shì 我/wǒ 昨天/zuótiān 买/mǎi （　） 衣服/yīfu 。"), ["的/de", "得/de", "地/de", "了/le"],
        ["", "得 needs a description of how after it.", "地 comes before a verb.", "这是我昨天买了衣服 isn't grammatical."],
        "Clause modifying a noun: **的**.", "These are the clothes I bought yesterday."),
      Q("degree", "Which sentence is correct?", ["他/tā 说/shuō 中文/Zhōngwén 说/shuō 得/de 很/hěn 好/hǎo 。", "他/tā 说/shuō 中文/Zhōngwén 得/de 很/hěn 好/hǎo 。", "他/tā 说/shuō 得/de 中文/Zhōngwén 很/hěn 好/hǎo 。", "他/tā 说/shuō 中文/Zhōngwén 很/hěn 好/hǎo 得/de 。"],
        ["", "得 must follow the verb directly — repeat 说.", "The object can't go between 得 and the adjective.", "得 comes before the adjective."],
        "Repeat the verb: **说中文说得很好**.", "He speaks Chinese very well."),
      Q("degree", "Which sentence means 'He doesn't run fast'?", ["他/tā 跑/pǎo 得/de 不/bú 快/kuài 。", "他/tā 不/bù 跑/pǎo 得/de 快/kuài 。", "他/tā 跑/pǎo 不/bu 得/de 快/kuài 。", "他/tā 没/méi 跑/pǎo 得/de 快/kuài 。"],
        ["", "不 goes after 得, before the adjective.", "Not grammatical.", "没 isn't used with degree complements."],
        "Negative: verb + 得 + **不** + adj.", "He doesn't run fast."),
      Q("wan", zh("我/wǒ 已经/yǐjīng 做/zuò （　） 作业/zuòyè 了/le ， 可以/kěyǐ 出去/chūqù 玩儿/wánr 吗/ma ？"), ["完/wán", "到/dào", "见/jiàn", "懂/dǒng"],
        ["", "做到 = 'achieve' — not 'finish homework'.", "见 is for seeing/hearing.", "做懂 isn't a word."],
        "Finished: **做完**.", "I've finished my homework — can I go out and play?"),
      Q("wan", "What does 「" + zh("我/wǒ 看/kàn 完/wán 了/le 这/zhè 本/běn 书/shū 。") + "」 mean?", ["I've finished reading this book.", "I've read this book before.", "I saw this book.", "I understood this book."],
        ["", "That's 看过.", "That's 看见.", "That's 看懂."],
        "完 = **finished**.", ""),
      Q("daojian", zh("我/wǒ 找/zhǎo （　） 我/wǒ 的/de 钥匙/yàoshi 了/le ！ 在/zài 沙发/shāfā 下面/xiàmiàn 。"), ["到/dào", "完/wán", "懂/dǒng", "会/huì"],
        ["", "找完 = 'finished searching' — not 'found'.", "找懂 isn't a word.", "找会 isn't a word."],
        "Found: **找到**.", "I found my keys! They were under the sofa."),
      Q("daojian", zh("你/nǐ 听/tīng （　） 了/le 吗/ma ？ 外面/wàimiàn 有人/yǒurén 叫/jiào 你/nǐ 。"), ["见/jiàn", "完/wán", "懂/dǒng", "会/huì"],
        ["", "听完 = 'finished listening'.", "听懂 = 'understood' — the question is whether you heard someone.", "听会 isn't a word."],
        "Heard: **听见**.", "Did you hear that? Someone outside is calling you."),
      Q("budong", zh("老师/lǎoshī 说/shuō 得/de 太/tài 快/kuài ， 我/wǒ 听/tīng 不/bu （　） 。"), ["懂/dǒng", "见/jiàn", "完/wán", "会/huì"],
        ["", "听不见 = 'can't hear' (too quiet) — the problem is speed.", "听不完 = 'can't listen to it all'.", "听不会 isn't a word."],
        "Can't understand: **听不懂**.", "The teacher speaks too fast — I can't understand."),
      Q("budong", zh("这/zhè 本/běn 书/shū 是/shì 中文/Zhōngwén 的/de ， 我/wǒ 看/kàn （　） 。"), ["不/bu 懂/dǒng", "没/méi 懂/dǒng", "不/bú 会/huì 懂/dǒng", "懂/dǒng 不/bu"],
        ["", "看没懂 isn't grammatical.", "看不会懂 isn't grammatical.", "The order is 看不懂."],
        "**Verb + 不懂**.", "This book is in Chinese — I can't understand it."),
      Q("haonan", zh("这个/zhège 汉字/Hànzì 很/hěn （　） 写/xiě ， 有/yǒu 二十/èrshí 多/duō 画/huà 。"), ["难/nán", "好/hǎo", "容/róng", "多/duō"],
        ["", "Twenty strokes don't make it easy.", "容 alone isn't used — 容易.", "多写 = 'write more'."],
        "Hard to: **难 + verb**.", "This character is hard to write — it has over twenty strokes."),
      Q("haonan", zh("这/zhè 家/jiā 的/de 饺子/jiǎozi 很/hěn （　） 吃/chī ， 你/nǐ 一定/yídìng 要/yào 试试/shìshi ！"), ["好/hǎo", "难/nán", "可/kě", "多/duō"],
        ["", "难吃 = 'tastes bad' — then you wouldn't recommend it.", "可吃 isn't a word.", "多吃 = 'eat more'."],
        "Tasty: **好吃**.", "The dumplings here are delicious — you have to try them!")])

# ---------------------------------------------------------------- 06 time clauses & connectors
quiz("06_connectors", "zh-a2-connectors", "Time & Logic: 以前 / 以后, 的时候, 从…到…, 因为…所以, 但是, 或者 / 还是, 离",
     "Before/after, when, from … to …, because … so, but, 'or' in statements vs questions, and distance with 离.",
     [P("yiqianhou", "Time / verb + 以前 / 以后", "以前 = before; 以后 = after. They follow the time or the event.",
        "- 到北京**以后**，给我打电话.\n- 三年**以前**，我还不会说中文.",
        [("到/dào 北京/Běijīng 以后/yǐhòu ， 给/gěi 我/wǒ 打/dǎ 电话/diànhuà 。", "Call me after you arrive in Beijing.")]),
      P("deshihou", "…的时候: when", "Clause + 的时候 = when / while ….",
        "- 我小**的时候**很喜欢画画儿.\n- 我上大学**的时候**学过法语.",
        [("我/wǒ 小/xiǎo 的/de 时候/shíhou 很/hěn 喜欢/xǐhuan 画画儿/huà huàr 。", "When I was little, I loved drawing.")]),
      P("congdao", "从 A 到 B: from A to B", "从 … 到 … for time and place.",
        "- 我**从**九点**到**五点工作.\n- **从**我家**到**学校要二十分钟.",
        [("我/wǒ 从/cóng 九/jiǔ 点/diǎn 到/dào 五/wǔ 点/diǎn 工作/gōngzuò 。", "I work from nine to five.")]),
      P("yinwei", "因为 … 所以 …: because … so", "因为 introduces the reason, 所以 the result. Either can stand alone.",
        "- **因为**下雨，**所以**比赛取消了.",
        [("因为/yīnwèi 下雨/xià yǔ ， 所以/suǒyǐ 比赛/bǐsài 取消/qǔxiāo 了/le 。", "The match was cancelled because of the rain.")]),
      P("danshi", "可是 / 但是: but", "可是 and 但是 both mean 'but' and start the second clause. 可是 is a bit more spoken.",
        "- 这件衣服很漂亮，**可是**太贵了.",
        [("我/wǒ 想/xiǎng 去/qù ， 但是/dànshì 没有/méiyǒu 时间/shíjiān 。", "I want to go, but I don't have time.")]),
      P("huozhe", "或者 vs 还是: or", "或者 = or in **statements** (either is fine). 还是 = or in **questions** (choose one).",
        "- 我们周末去爬山**或者**去游泳吧.\n- 你想喝茶**还是**咖啡?",
        [("你/nǐ 想/xiǎng 喝/hē 茶/chá 还是/háishi 咖啡/kāfēi ？", "Would you like tea or coffee?")]),
      P("li", "A 离 B + 近 / 远: distance", "A 离 B 很近 / 很远 = A is close to / far from B.",
        "- 我家**离**公司很近.",
        [("我/wǒ 家/jiā 离/lí 公司/gōngsī 很/hěn 近/jìn 。", "My home is close to the office.")])],
     [Q("yiqianhou", zh("到/dào 北京/Běijīng （　） ， 给/gěi 我/wǒ 打/dǎ 个/ge 电话/diànhuà 。"), ["以后/yǐhòu", "以前/yǐqián", "时间/shíjiān", "后来/hòulái"],
        ["", "You can't call 'before arriving' to report arriving.", "时间 = 'time' (a noun) — doesn't follow a verb like this.", "后来 = 'later on' (past narrative), not after a verb."],
        "After: **以后**.", "Give me a call after you arrive in Beijing."),
      Q("yiqianhou", zh("三/sān 年/nián （　） ， 我/wǒ 还/hái 不/bú 会/huì 说/shuō 中文/Zhōngwén ， 现在/xiànzài 说/shuō 得/de 很/hěn 好/hǎo 。"), ["以前/yǐqián", "以后/yǐhòu", "的时候/de shíhou", "时候/shíhou"],
        ["", "以后 = 'in three years' — clashes with 现在说得很好.", "三年的时候 = 'at age three'.", "时候 needs 的."],
        "Ago: **以前**.", "Three years ago I couldn't speak Chinese; now I speak it well."),
      Q("deshihou", zh("我/wǒ 小/xiǎo （　） ， 很/hěn 喜欢/xǐhuan 画画儿/huà huàr 。"), ["的时候/de shíhou", "以后/yǐhòu", "时间/shíjiān", "以前/yǐqián"],
        ["", "小以后 isn't grammatical.", "小时间 isn't grammatical.", "小以前 isn't grammatical."],
        "When: **的时候**.", "When I was little, I loved drawing."),
      Q("deshihou", "Which sentence is correct?", ["我/wǒ 上/shàng 大学/dàxué 的/de 时候/shíhou 学/xué 过/guo 法语/Fǎyǔ 。", "我/wǒ 的/de 时候/shíhou 上/shàng 大学/dàxué 学/xué 过/guo 法语/Fǎyǔ 。", "上/shàng 大学/dàxué 我/wǒ 的/de 时候/shíhou 学/xué 过/guo 法语/Fǎyǔ 。", "我/wǒ 上/shàng 大学/dàxué 时候/shíhou 的/de 学/xué 过/guo 法语/Fǎyǔ 。"],
        ["", "的时候 follows the whole clause.", "的时候 follows the whole clause, subject included.", "The order is 的时候."],
        "Clause + **的时候**.", "I studied French when I was at university."),
      Q("congdao", zh("我/wǒ 每天/měitiān （　） 九/jiǔ 点/diǎn 到/dào 五/wǔ 点/diǎn 工作/gōngzuò 。"), ["从/cóng", "在/zài", "离/lí", "到/dào"],
        ["", "在九点到五点 isn't the pattern.", "离 = distance from.", "到九点到五点 isn't grammatical."],
        "From … to: **从…到**.", "I work from nine to five every day."),
      Q("congdao", zh("从/cóng 我/wǒ 家/jiā （　） 学校/xuéxiào 要/yào 二十/èrshí 分钟/fēnzhōng 。"), ["到/dào", "离/lí", "在/zài", "对/duì"],
        ["", "从 … 离 isn't the pattern.", "从 … 在 isn't the pattern.", "对 = 'towards / for'."],
        "**从 … 到 …**.", "It takes twenty minutes from my home to school."),
      Q("yinwei", zh("（　） 下雨/xià yǔ ， 所以/suǒyǐ 比赛/bǐsài 取消/qǔxiāo 了/le 。"), ["因为/yīnwèi", "所以/suǒyǐ", "但是/dànshì", "如果/rúguǒ"],
        ["", "所以 introduces the result, which comes later.", "但是 = 'but'.", "如果 = 'if' — doesn't pair with 所以 and a past 了."],
        "Because: **因为…所以**.", "The match was cancelled because of the rain."),
      Q("yinwei", zh("因为/yīnwèi 他/tā 病/bìng 了/le ， （　） 没/méi 来/lái 上课/shàngkè 。"), ["所以/suǒyǐ", "但是/dànshì", "因为/yīnwèi", "可是/kěshì"],
        ["", "但是 = 'but' — no contrast here.", "Another 因为 isn't needed.", "可是 = 'but'."],
        "So: **所以**.", "He was ill, so he didn't come to class."),
      Q("danshi", zh("这/zhè 件/jiàn 衣服/yīfu 很/hěn 漂亮/piàoliang ， （　） 太/tài 贵/guì 了/le 。"), ["可是/kěshì", "所以/suǒyǐ", "因为/yīnwèi", "或者/huòzhě"],
        ["", "所以 = 'so' — 'pretty, so too expensive' is illogical.", "因为 introduces a reason.", "或者 = 'or'."],
        "But: **可是**.", "This piece of clothing is pretty, but too expensive."),
      Q("danshi", zh("我/wǒ 很/hěn 想/xiǎng 去/qù ， （　） 没有/méiyǒu 时间/shíjiān 。"), ["但是/dànshì", "所以/suǒyǐ", "或者/huòzhě", "还是/háishi"],
        ["", "所以 = 'so' — not a contrast.", "或者 = 'or'.", "还是 = 'or (question)' / 'still'."],
        "But: **但是**.", "I'd really like to go, but I don't have time."),
      Q("huozhe", zh("我们/wǒmen 周末/zhōumò 去/qù 爬山/páshān （　） 去/qù 游泳/yóuyǒng 吧/ba 。"), ["或者/huòzhě", "还是/háishi", "和/hé", "也/yě"],
        ["", "还是 is 'or' in questions — this is a suggestion.", "和 can't link verb phrases.", "也 = 'also'."],
        "Or (statement): **或者**.", "Let's go hiking or swimming this weekend."),
      Q("huozhe", zh("你/nǐ 想/xiǎng 喝/hē 茶/chá （　） 咖啡/kāfēi ？"), ["还是/háishi", "或者/huòzhě", "和/hé", "也/yě"],
        ["", "或者 doesn't make an either-or question.", "茶和咖啡 = 'tea and coffee' — not a choice.", "也 = 'also'."],
        "Or (question): **还是**.", "Would you like tea or coffee?"),
      Q("li", zh("我/wǒ 家/jiā （　） 公司/gōngsī 很/hěn 近/jìn ， 走路/zǒulù 五/wǔ 分钟/fēnzhōng 。"), ["离/lí", "从/cóng", "到/dào", "在/zài"],
        ["", "从 needs 到 and a verb.", "到 isn't used for distance like this.", "在 = 'at'."],
        "Distance: **离**.", "My home is close to the office — a five-minute walk."),
      Q("li", "Which sentence is correct?", ["学校/xuéxiào 离/lí 我/wǒ 家/jiā 很/hěn 远/yuǎn 。", "学校/xuéxiào 从/cóng 我/wǒ 家/jiā 很/hěn 远/yuǎn 。", "学校/xuéxiào 离/lí 我/wǒ 家/jiā 远/yuǎn 很/hěn 。", "离/lí 学校/xuéxiào 我/wǒ 家/jiā 很/hěn 远/yuǎn 。"],
        ["", "Distance uses 离, not 从.", "很 comes before the adjective.", "A comes before 离."],
        "**A 离 B 很远**.", "The school is far from my home.")])

# ---------------------------------------------------------------- 07 quantities
quiz("07_quantities", "zh-a2-quantities", "Counting: measure words, 几, 每, 半, 万, money, 有的 / 一些, 什么都",
     "The common measure words, 'several' with 几, every (每), half (半), ten thousand (万), prices, 'some', and 'anything / everything'.",
     [P("mw", "Measure words", "Number / 这 / 那 + measure word + noun. Common ones: 本 (books), 张 (flat things), 件 (clothes, matters), 杯 (cups of), 条 (long things: roads, trousers, fish), {只|zhī} (animals).",
        "- 两**件**衣服, 三**张**纸, 一**杯**咖啡, 一**条**裤子.",
        [("我/wǒ 买/mǎi 了/le 两/liǎng 件/jiàn 衣服/yīfu 。", "I bought two pieces of clothing.")]),
      P("ji", "几 + measure word: several", "In a statement, 几 + measure word = a few, several.",
        "- 我买了**几**本书.",
        [("我/wǒ 买/mǎi 了/le 几/jǐ 本/běn 书/shū 。", "I bought a few books.")]),
      P("mei", "每 + measure word (+ 都): every", "每 + (measure word) + noun, usually with 都 before the verb.",
        "- 我**每**天**都**跑步.",
        [("我/wǒ 每/měi 天/tiān 都/dōu 跑步/pǎobù 。", "I run every day.")]),
      P("ban", "半: half", "半 + measure word = half a …; number + measure word + 半 = … and a half (一个半小时).",
        "- **半**个小时 (half an hour), 一个**半**小时 (an hour and a half).",
        [("我/wǒ 等/děng 了/le 一个/yí ge 半/bàn 小时/xiǎoshí 。", "I waited an hour and a half.")]),
      P("wan", "万: ten thousand; money", "Chinese counts in 万 (10,000): 五万 = 50,000. Money: 块 (spoken) / 元 (written) + 毛 (0.1). 三块五 = ¥3.50.",
        "- 一**万** = 10,000, 十**万** = 100,000.\n- 三**块**五(毛) = ¥3.50.",
        [("这个/zhège 手机/shǒujī 三千/sānqiān 五/wǔ 百/bǎi 块/kuài 。", "This phone costs 3,500 yuan.")]),
      P("youde", "有的 vs 一些: some", "有的 + noun = some (of a group), often contrasted: 有的…，有的…. 一些 + noun = some, a few (amount).",
        "- **有的**人喜欢茶，**有的**人喜欢咖啡.\n- 我想买**一些**水果.",
        [("有的/yǒude 人/rén 喜欢/xǐhuan 茶/chá ， 有的/yǒude 人/rén 喜欢/xǐhuan 咖啡/kāfēi 。", "Some people like tea, some like coffee.")]),
      P("shenmedou", "什么 / 谁 / 哪儿 + 都: everything / everyone / everywhere", "Question word + 都 (+ 不) = every- / (not) any-.",
        "- 我**什么都**不想做.\n- 他**谁都**认识.",
        [("我/wǒ 什么/shénme 都/dōu 不/bù 想/xiǎng 做/zuò 。", "I don't feel like doing anything.")])],
     [Q("mw", zh("我/wǒ 买/mǎi 了/le 两/liǎng （　） 衣服/yīfu 。"), ["件/jiàn", "本/běn", "张/zhāng", "条/tiáo"],
        ["", "本 is for books.", "张 is for flat things like paper.", "条 is for trousers, not clothes in general."],
        "Clothes: **件**.", "I bought two pieces of clothing."),
      Q("mw", zh("桌子/zhuōzi 上/shang 有/yǒu 三/sān （　） 纸/zhǐ 。"), ["张/zhāng", "件/jiàn", "本/běn", "只/zhī"],
        ["", "件 is for clothes and matters.", "本 is for books.", "{只|zhī} is for animals."],
        "Flat things: **张**.", "There are three sheets of paper on the table."),
      Q("mw", zh("服务员/fúwùyuán ， 我/wǒ 要/yào 一/yì （　） 咖啡/kāfēi 。"), ["杯/bēi", "张/zhāng", "本/běn", "条/tiáo"],
        ["", "张 is for flat things.", "本 is for books.", "条 is for long things."],
        "A cup of: **杯**.", "Waiter, a cup of coffee, please."),
      Q("ji", zh("我/wǒ 买/mǎi 了/le （　） 本/běn 书/shū ， 都/dōu 很/hěn 有意思/yǒu yìsi 。"), ["几/jǐ", "什么/shénme", "一些/yìxiē", "有的/yǒude"],
        ["", "什么本书 isn't grammatical.", "一些 doesn't take a measure word: 一些书.", "有的 doesn't take a measure word."],
        "Several: **几 + measure word**.", "I bought a few books — they're all interesting."),
      Q("ji", "In 「" + zh("我/wǒ 有/yǒu 几/jǐ 个/ge 中国/Zhōngguó 朋友/péngyou 。") + "」, what does 几 mean?", ["a few, several", "how many?", "a lot of", "only one"],
        ["", "In a statement (。), 几 isn't a question.", "That's 很多.", "That's 只有一个."],
        "In a statement: 几 = **several**.", "I have a few Chinese friends."),
      Q("mei", zh("我/wǒ （　） 天/tiān 都/dōu 跑步/pǎobù 。"), ["每/měi", "各/gè", "都/dōu", "有/yǒu"],
        ["", "各天 isn't used.", "都天 isn't grammatical.", "有天 = 'one day'."],
        "Every: **每…都**.", "I run every day."),
      Q("mei", "Which sentence is correct?", ["我们/wǒmen 每/měi 个/ge 人/rén 都/dōu 有/yǒu 一/yì 本/běn 书/shū 。", "我们/wǒmen 每/měi 个/ge 人/rén 有/yǒu 都/dōu 一/yì 本/běn 书/shū 。", "我们/wǒmen 都/dōu 每/měi 个/ge 人/rén 有/yǒu 一/yì 本/běn 书/shū 。", "我们/wǒmen 每/měi 人/rén 个/ge 都/dōu 有/yǒu 一/yì 本/běn 书/shū 。"],
        ["", "都 goes before the verb.", "都 comes after the 每 phrase.", "The order is 每个人."],
        "每 + MW + noun + **都** + verb.", "Each of us has a book."),
      Q("ban", zh("我/wǒ 在/zài 这儿/zhèr 等/děng 了/le 一个/yí ge （　） 小时/xiǎoshí 。"), ["半/bàn", "一半/yíbàn", "半个/bàn ge", "两/liǎng"],
        ["", "一半 = 'one half (of something)'.", "一个半个 has one 个 too many.", "一个两小时 isn't grammatical."],
        "And a half: **一个半小时**.", "I've been waiting here for an hour and a half."),
      Q("ban", "How do you say 'half an hour'?", ["半/bàn 个/ge 小时/xiǎoshí", "一/yí 半/bàn 小时/xiǎoshí", "小时/xiǎoshí 半/bàn", "半/bàn 小时/xiǎoshí 个/ge"],
        ["", "一半 = 'a half (portion)', not before a measure.", "半 goes before.", "个 goes before the noun."],
        "**半个小时**.", ""),
      Q("wan", "How do you say 50,000 yuan?", ["五万/wǔwàn 块/kuài", "五十千/wǔshí qiān 块/kuài", "五千/wǔqiān 块/kuài", "五百万/wǔbǎi wàn 块/kuài"],
        ["", "Chinese doesn't count in 'fifty thousands'.", "五千 = 5,000.", "五百万 = 5,000,000."],
        "50,000 = **五万**.", ""),
      Q("wan", "How do you say ¥3.50 in everyday speech?", ["三/sān 块/kuài 五/wǔ", "三/sān 块/kuài 五十/wǔshí", "三/sān 毛/máo 五/wǔ", "五/wǔ 块/kuài 三/sān"],
        ["", "Prices aren't said like that — 五 after 块 already means 5 毛 (50 fen).", "三毛五 = ¥0.35.", "That's ¥5.30."],
        "**三块五(毛)**.", ""),
      Q("youde", zh("（　） 人/rén 喜欢/xǐhuan 喝/hē 茶/chá ， 有的/yǒude 人/rén 喜欢/xǐhuan 喝/hē 咖啡/kāfēi 。"), ["有的/yǒude", "一些/yìxiē", "都/dōu", "每/měi"],
        ["", "The contrast pattern is 有的…，有的….", "都人 isn't grammatical.", "每人 contradicts 有的人."],
        "Some …, some …: **有的…有的…**.", "Some people like tea, some like coffee."),
      Q("youde", zh("我/wǒ 想/xiǎng 去/qù 超市/chāoshì 买/mǎi （　） 水果/shuǐguǒ 。"), ["一些/yìxiē", "有的/yǒude", "每/měi", "几/jǐ"],
        ["", "有的 picks some out of a group — not an amount to buy.", "每水果 isn't grammatical.", "几 needs a measure word."],
        "Some (amount): **一些**.", "I want to go to the supermarket to buy some fruit."),
      Q("shenmedou", zh("我/wǒ 太/tài 累/lèi 了/le ， （　） 都/dōu 不/bù 想/xiǎng 做/zuò 。"), ["什么/shénme", "怎么/zěnme", "哪/nǎ", "谁/shéi"],
        ["", "怎么都不想做 = 'no matter how, I don't want to' — not 'anything'.", "哪 needs a measure word / 儿.", "谁 = 'anyone' — but 做 needs a thing."],
        "Anything: **什么都**.", "I'm so tired, I don't feel like doing anything."),
      Q("shenmedou", zh("他/tā 朋友/péngyou 很/hěn 多/duō ， 学校/xuéxiào 里/lǐ （　） 都/dōu 认识/rènshi 他/tā 。"), ["谁/shéi", "什么/shénme", "哪儿/nǎr", "怎么/zěnme"],
        ["", "什么 = 'anything' — people know him, not things.", "哪儿 = 'everywhere'.", "怎么 = 'however'."],
        "Everyone: **谁都**.", "He has lots of friends — everyone at school knows him.")])

# ---------------------------------------------------------------- 08 verbs & modals
quiz("08_verbs", "zh-a2-verbs", "Verbs: 想 vs 要, 应该, 会 (will), 没办法, verb + 一下, double objects",
     "Would like (想) vs want (要), should, will, can't (no way), doing something briefly, and verbs with two objects.",
     [P("xiangyao", "想 vs 要", "想 + verb = would like to (softer); 想 + person/place = miss. 要 + noun = want (to have); 要 + verb = want to / be going to (stronger).",
        "- 我**想**家 (I'm homesick).\n- 我**要**一杯茶 — not ~~我想一杯茶~~.",
        [("我/wǒ 很/hěn 想/xiǎng 家/jiā 。", "I'm really homesick.")]),
      P("yinggai", "应该 / 该 + verb: should", "应该 (yīnggāi) = should, ought to. 该…了 = it's time to ….",
        "- 你病了，**应该**多休息.\n- 十点了，我**该**走**了**.",
        [("你/nǐ 应该/yīnggāi 多/duō 休息/xiūxi 。", "You should rest more.")]),
      P("huiwill", "会 + verb: will (likely)", "会 also predicts: it will / is likely to happen. Often with 的 at the end for certainty.",
        "- 明天**会**下雨吗?\n- 他一定**会**来**的**.",
        [("别/bié 担心/dānxīn ， 他/tā 一定/yídìng 会/huì 来/lái 的/de 。", "Don't worry, he'll definitely come.")]),
      P("meibanfa", "没办法 + verb: can't (no way)", "没(有)办法 = there's no way to / nothing can be done.",
        "- 我今天很忙，**没办法**陪你去.",
        [("我/wǒ 没/méi 办法/bànfǎ 帮/bāng 你/nǐ 。", "There's no way I can help you.")]),
      P("yixia", "Verb + 一下 / verb-verb: briefly", "Verb + 一下 or doubling the verb (看看, 试试) softens it: 'have a quick …'.",
        "- 请等**一下**.\n- 你**试试**这件衣服吧.",
        [("你/nǐ 试试/shìshi 这/zhè 件/jiàn 衣服/yīfu 吧/ba 。", "Why don't you try this on.")]),
      P("double", "Verb + person + thing (double objects)", "给, 教, 问, 告诉 … take the person first, then the thing.",
        "- 他给了**我一本书**.\n- 老师问了**我们一个问题**.",
        [("他/tā 给/gěi 了/le 我/wǒ 一/yì 本/běn 书/shū 。", "He gave me a book.")])],
     [Q("xiangyao", zh("A： 你/nǐ 想/xiǎng 喝/hē 什么/shénme ？ // B： 我/wǒ （　） 一/yì 杯/bēi 茶/chá 。"), ["要/yào", "想/xiǎng", "会/huì", "应该/yīnggāi"],
        ["", "想 + noun means 'miss' — 'I miss a cup of tea'.", "会 needs a verb.", "应该 needs a verb."],
        "Want (+ thing): **要**.", "A: What would you like to drink? B: A cup of tea, please."),
      Q("xiangyao", zh("我/wǒ 来/lái 中国/Zhōngguó 半/bàn 年/nián 了/le ， 很/hěn （　） 家/jiā 。"), ["想/xiǎng", "要/yào", "会/huì", "该/gāi"],
        ["", "要家 = 'want a home'.", "会家 isn't grammatical.", "该家 isn't grammatical."],
        "Miss: **想**.", "I've been in China for half a year and I'm really homesick."),
      Q("yinggai", zh("你/nǐ 病/bìng 了/le ， （　） 多/duō 休息/xiūxi 。"), ["应该/yīnggāi", "会/huì", "还是/háishi", "就是/jiùshì"],
        ["", "会多休息 = 'will rest more' — a prediction, not advice.", "还是 would need a different structure.", "就是 = 'precisely'."],
        "Should: **应该**.", "You're ill — you should rest more."),
      Q("yinggai", zh("已经/yǐjīng 十/shí 点/diǎn 了/le ， 我/wǒ （　） 回家/huíjiā 了/le 。"), ["该/gāi", "会/huì", "在/zài", "过/guò"],
        ["", "会…了 isn't 'it's time to'.", "在回家了 isn't grammatical.", "过回家 isn't grammatical."],
        "It's time to: **该…了**.", "It's already ten — time for me to go home."),
      Q("huiwill", zh("你/nǐ 看/kàn ， 天/tiān 这么/zhème 黑/hēi ， 明天/míngtiān （　） 下雨/xià yǔ 吗/ma ？"), ["会/huì", "能/néng", "可以/kěyǐ", "想/xiǎng"],
        ["", "能 = 'be able'.", "可以 = 'be allowed'.", "想 = 'want to' — weather doesn't want."],
        "Will (prediction): **会**.", "Look how dark the sky is — will it rain tomorrow?"),
      Q("huiwill", zh("别/bié 担心/dānxīn ， 他/tā 一定/yídìng （　） 来/lái 的/de 。"), ["会/huì", "可以/kěyǐ", "想/xiǎng", "应该/yīnggāi"],
        ["", "一定可以来的 isn't natural.", "一定想来的 isn't natural.", "一定应该 isn't grammatical."],
        "Certain prediction: **一定会…的**.", "Don't worry, he'll definitely come."),
      Q("meibanfa", zh("我/wǒ 今天/jīntiān 很/hěn 忙/máng ， （　） 陪/péi 你/nǐ 去/qù 。"), ["没办法/méi bànfǎ", "没有法/méiyǒu fǎ", "不办法/bú bànfǎ", "没法办/méi fǎ bàn"],
        ["", "没有法 isn't a phrase.", "办法 is a noun — negate it with 没.", "没法办 = 'it can't be dealt with'."],
        "No way to: **没办法**.", "I'm really busy today — I can't go with you."),
      Q("meibanfa", "Which sentence is correct?", ["我/wǒ 没/méi 办法/bànfǎ 帮/bāng 你/nǐ 。", "我/wǒ 不/bú 办法/bànfǎ 帮/bāng 你/nǐ 。", "我/wǒ 没/méi 帮/bāng 你/nǐ 办法/bànfǎ 。", "我/wǒ 办法/bànfǎ 没有/méiyǒu 帮/bāng 你/nǐ 。"],
        ["", "办法 is a noun — 没, not 不.", "没办法 comes before the verb.", "The order is 没有办法."],
        "**没办法 + verb**.", "There's no way I can help you."),
      Q("yixia", zh("请/qǐng 等/děng （　） ， 他/tā 马上/mǎshàng 就/jiù 来/lái 。"), ["一下/yíxià", "一点/yìdiǎn", "一些/yìxiē", "一次/yí cì"],
        ["", "等一点 isn't natural.", "一些 goes before nouns.", "等一次 = 'wait once'."],
        "Briefly: **verb + 一下**.", "Please wait a moment, he'll be right here."),
      Q("yixia", zh("这/zhè 件/jiàn 衣服/yīfu 很/hěn 漂亮/piàoliang ， 你/nǐ （　） 吧/ba 。"), ["试试/shìshi", "试一/shì yī", "一试/yí shì", "试和试/shì hé shì"],
        ["", "试一 is incomplete — 试一试 or 试一下.", "一试 can't stand alone here.", "和 can't link verbs."],
        "Doubled verb: **试试**.", "This dress is lovely — why don't you try it on."),
      Q("double", "Which sentence is correct?", ["他/tā 给/gěi 了/le 我/wǒ 一/yì 本/běn 书/shū 。", "他/tā 给/gěi 了/le 一/yì 本/běn 书/shū 我/wǒ 。", "他/tā 我/wǒ 给/gěi 了/le 一/yì 本/běn 书/shū 。", "他/tā 一/yì 本/běn 书/shū 给/gěi 了/le 我/wǒ 。"],
        ["", "The person comes before the thing.", "The person comes after the verb.", "The thing can't go before the verb like this."],
        "Verb + **person + thing**.", "He gave me a book."),
      Q("double", zh("上课/shàngkè 的/de 时候/shíhou ， 老师/lǎoshī （　） 我们/wǒmen 一个/yí ge 问题/wèntí 。"), ["问/wèn 了/le", "说/shuō 了/le", "对/duì 了/le", "跟/gēn 了/le"],
        ["", "说 doesn't take a person as the first object.", "对了 = 'that's right'.", "跟了 = 'followed'."],
        "Ask someone something: **问 + person + thing**.", "In class, the teacher asked us a question.")])

# ---------------------------------------------------------------- 09 HSK reading
quiz("09_hsk_reading", "zh-a2-hsk-reading", "HSK Reading: 判断对错 & 阅读理解",
     "HSK-style reading: decide whether the ★ statement is true, or answer the ★ question about a short text. Everything hinges on the A2 grammar.",
     [P("panduan", "判断对错: true or false?", "Read the passage, then decide if the ★ statement matches it.",
        "Grammar traps to watch for:\n- **不…了** (not anymore) vs **没** (didn't).\n- **还没** = not yet; **已经…了** = already.\n- **过** = has ever done.\n- **比 / 没有 / 一样** comparisons — work out who is taller/older.\n- **快…了** = not yet, but soon.",
        [("我/wǒ 以前/yǐqián 喜欢/xǐhuan 喝/hē 咖啡/kāfēi ， 现在/xiànzài 不/bù 喝/hē 了/le 。", "I used to like coffee, but I don't drink it anymore.")]),
      P("yuedu", "阅读理解: answer the ★ question", "Read the short passage and pick the answer it supports. Often one detail — a time, a comparison, a reason with 因为 — decides it.",
        "- Look for the connector: 因为 / 所以 / 但是.\n- Do the arithmetic with times and ages.\n- Wrong options often repeat words from the text but change their meaning.",
        [("因为/yīnwèi 路/lù 上/shang 车/chē 很/hěn 多/duō ， 我/wǒ 晚/wǎn 到/dào 了/le 。", "There was a lot of traffic, so I arrived late.")])],
     [tf("panduan", "我/wǒ 以前/yǐqián 很/hěn 喜欢/xǐhuan 喝/hē 咖啡/kāfēi ， 每天/měitiān 喝/hē 三/sān 杯/bēi ， 可是/kěshì 现在/xiànzài 不/bù 喝/hē 了/le 。", "他/tā 现在/xiànzài 不/bù 喝/hē 咖啡/kāfēi 。", True,
         "不喝了 = he doesn't drink it anymore — so the statement is true.", "不…了 = **not anymore**.",
         "I used to love coffee and drank three cups a day, but now I don't drink it anymore. ★ He doesn't drink coffee now."),
      tf("panduan", "我/wǒ 来/lái 中国/Zhōngguó 三/sān 年/nián 了/le ， 去/qù 过/guo 很/hěn 多/duō 地方/dìfang ， 可是/kěshì 还/hái 没/méi 去/qù 过/guo 上海/Shànghǎi 。", "他/tā 去/qù 过/guo 上海/Shànghǎi 。", False,
         "还没去过上海 = he hasn't been to Shanghai yet.", "还没…过 = **has never yet**.",
         "I've been in China for three years and have been to many places, but I haven't been to Shanghai yet. ★ He has been to Shanghai."),
      tf("panduan", "哥哥/gēge 比/bǐ 我/wǒ 大/dà 两/liǎng 岁/suì ， 我/wǒ 今年/jīnnián 十八/shíbā 岁/suì 。", "哥哥/gēge 今年/jīnnián 二十/èrshí 岁/suì 。", True,
         "18 + 2 = 20 — the statement is true.", "比 + adj + **amount**: two years older.",
         "My older brother is two years older than me; I'm eighteen this year. ★ My brother is twenty this year."),
      tf("panduan", "电影/diànyǐng 七/qī 点/diǎn 半/bàn 开始/kāishǐ ， 现在/xiànzài 已经/yǐjīng 七/qī 点/diǎn 四十/sìshí 了/le ， 我们/wǒmen 快/kuài 点儿/diǎnr 走/zǒu 吧/ba ！", "电影/diànyǐng 还/hái 没/méi 开始/kāishǐ 。", False,
         "It started at 7:30 and it's already 7:40 — so it has started.", "Work out the time: **已经** 7:40.",
         "The film starts at 7:30 and it's already 7:40 — let's hurry! ★ The film hasn't started yet."),
      tf("panduan", "小王/Xiǎo Wáng 跟/gēn 小李/Xiǎo Lǐ 一样/yíyàng 高/gāo ， 小李/Xiǎo Lǐ 比/bǐ 小张/Xiǎo Zhāng 高/gāo 。", "小张/Xiǎo Zhāng 比/bǐ 小王/Xiǎo Wáng 高/gāo 。", False,
         "Wang = Li, and Li is taller than Zhang — so Wang is taller than Zhang, not the other way round.", "Chain the comparisons: **一样** and **比**.",
         "Xiao Wang is as tall as Xiao Li, and Xiao Li is taller than Xiao Zhang. ★ Xiao Zhang is taller than Xiao Wang."),
      tf("panduan", "这/zhè 家/jiā 店/diàn 的/de 东西/dōngxi 又/yòu 便宜/piányi 又/yòu 好/hǎo ， 所以/suǒyǐ 每天/měitiān 都/dōu 有/yǒu 很/hěn 多/duō 人/rén 。", "这/zhè 家/jiā 店/diàn 的/de 东西/dōngxi 不/bú 贵/guì 。", True,
         "又便宜又好 — cheap means not expensive, so it's true.", "**又…又** = both … and.",
         "The things in this shop are cheap and good, so it's busy every day. ★ The things in this shop aren't expensive."),
      tf("panduan", "我/wǒ 刚/gāng 到/dào 家/jiā ， 还/hái 没/méi 吃饭/chīfàn 呢/ne ， 你/nǐ 等/děng 我/wǒ 一下/yíxià 。", "他/tā 已经/yǐjīng 吃/chī 了/le 饭/fàn 。", False,
         "还没吃饭呢 = he hasn't eaten yet.", "**还没…呢** = not yet.",
         "I've only just got home and haven't eaten yet — wait for me a moment. ★ He has already eaten."),
      reading("yuedu", "今天/jīntiān 我/wǒ 起床/qǐchuáng 起/qǐ 得/de 太/tài 晚/wǎn 了/le ， 路/lù 上/shang 车/chē 又/yòu 很/hěn 多/duō ， 九/jiǔ 点/diǎn 半/bàn 到/dào 公司/gōngsī ， 比/bǐ 平时/píngshí 晚/wǎn 了/le 一个/yí ge 小时/xiǎoshí 。", "他/tā 平时/píngshí 几/jǐ 点/diǎn 到/dào 公司/gōngsī ？",
              ["八/bā 点/diǎn 半/bàn", "九/jiǔ 点/diǎn 半/bàn", "十/shí 点/diǎn 半/bàn", "九/jiǔ 点/diǎn"],
              ["", "9:30 is when he arrived today.", "That would be an hour later, not earlier.", "比平时晚了一个小时 = an hour, not half an hour."],
              "9:30 − 1 hour = **8:30**.", "I got up too late today and there was lots of traffic, so I got to the office at 9:30 — an hour later than usual. ★ When does he usually get to the office?"),
      reading("yuedu", "我/wǒ 有/yǒu 两/liǎng 个/ge 姐姐/jiějie 。 大姐/dàjiě 是/shì 医生/yīshēng ， 二姐/èrjiě 是/shì 老师/lǎoshī 。 二姐/èrjiě 没有/méiyǒu 大姐/dàjiě 忙/máng ， 可是/kěshì 比/bǐ 大姐/dàjiě 累/lèi 。", "关于/guānyú 二姐/èrjiě ， 可以/kěyǐ 知道/zhīdào ：",
              ["比/bǐ 大姐/dàjiě 累/lèi", "比/bǐ 大姐/dàjiě 忙/máng", "是/shì 医生/yīshēng", "没有/méiyǒu 工作/gōngzuò"],
              ["", "没有大姐忙 = she's NOT as busy.", "The doctor is the eldest sister.", "She's a teacher."],
              "**没有 … 忙** but **比 … 累**.", "I have two older sisters. The eldest is a doctor, the second a teacher. The second isn't as busy as the eldest, but she's more tired. ★ What do we know about the second sister?"),
      reading("yuedu", "我/wǒ 学/xué 了/le 一/yì 年/nián 汉语/Hànyǔ 了/le 。 我/wǒ 能/néng 看/kàn 懂/dǒng 简单/jiǎndān 的/de 书/shū ， 可是/kěshì 听/tīng 不/bu 懂/dǒng 中国人/Zhōngguórén 说话/shuōhuà ， 因为/yīnwèi 他们/tāmen 说/shuō 得/de 太/tài 快/kuài 了/le 。", "他/tā 为什么/wèishénme 听/tīng 不/bu 懂/dǒng ？",
              ["中国人/Zhōngguórén 说/shuō 得/de 太/tài 快/kuài", "他/tā 没/méi 学/xué 过/guo 汉语/Hànyǔ", "书/shū 太/tài 难/nán 了/le", "他/tā 听/tīng 不/bu 见/jiàn"],
              ["", "He has studied for a year.", "He can read simple books.", "听不见 = can't hear — it's about speed, not volume."],
              "The reason follows **因为**.", "I've been learning Chinese for a year. I can read simple books, but I can't understand Chinese people talking because they speak too fast. ★ Why can't he understand?"),
      reading("yuedu", "小明/Xiǎo Míng 每天/měitiān 早上/zǎoshang 一边/yìbiān 吃/chī 早饭/zǎofàn 一边/yìbiān 看/kàn 手机/shǒujī ， 妈妈/māma 总是/zǒngshì 说/shuō ： “ 别/bié 看/kàn 了/le ！ ”", "妈妈/māma 希望/xīwàng 小明/Xiǎo Míng ：",
              ["吃饭/chīfàn 的/de 时候/shíhou 不/bú 看/kàn 手机/shǒujī", "多/duō 看/kàn 手机/shǒujī", "不/bù 吃/chī 早饭/zǎofàn", "早/zǎo 点儿/diǎnr 起床/qǐchuáng"],
              ["", "别看了 = stop looking.", "She objects to the phone, not to breakfast.", "Getting up isn't mentioned."],
              "**别…了** = stop doing it.", "Every morning Xiao Ming looks at his phone while eating breakfast, and his mum always says: 'Stop looking at it!' ★ What does his mum want?")])

# ---------------------------------------------------------------- 10 HSK ordering
quiz("10_hsk_order", "zh-a2-hsk-order", "HSK Sentence Building: 排列顺序 & ★ ordering",
     "Put three parts A/B/C in order (HSK 排列顺序), and build sentences with A2 grammar (比, 得, 已经, 过, 一边, 离).",
     [P("paixu", "排列顺序: order A, B, C", "Find the part that can open the text (it has a subject / time and no connector), then follow the connectors.",
        "- 所以, 但是, 就, 然后, 最后 can't open the text — something must come before them.\n- 先 → 然后 → 最后.\n- 刚 … 就 … : the 就 part comes later.",
        [("我/wǒ 先/xiān 去/qù 银行/yínháng ， 然后/ránhòu 去/qù 超市/chāoshì 。", "First I go to the bank, then to the supermarket.")]),
      P("order2", "★ ordering with A2 grammar", "Rebuild the A2 patterns first: 比 + B + adj, verb + 得 + adj, 已经 + verb + 完, 一边 + verb.",
        "- Comparison: A 比 B 高 一点儿.\n- 中文 说 得 很好.\n- 离 + place + 不太 + 远.",
        [("我/wǒ 比/bǐ 他/tā 高/gāo 一点儿/yìdiǎnr 。", "I'm a bit taller than him.")])],
     [order3("paixu", ["所以/suǒyǐ 我/wǒ 今天/jīntiān 没/méi 去/qù 上班/shàngbān", "昨天/zuótiān 晚上/wǎnshang 我/wǒ 发烧/fāshāo 了/le", "现在/xiànzài 已经/yǐjīng 好/hǎo 多/duō 了/le"],
             "BAC", ["ACB", "CAB", "CBA"], ["所以 can't open the text.", "所以 needs the reason (B) before it.", "The fever (B) must come before 所以 (A)."],
             "**B** 昨天晚上我发烧了，**A** 所以我今天没去上班，**C** 现在已经好多了。", "I had a fever last night, so I didn't go to work today; I'm much better now."),
      order3("paixu", ["然后/ránhòu 去/qù 超市/chāoshì 买/mǎi 东西/dōngxi", "我/wǒ 下/xià 了/le 班/bān 先/xiān 去/qù 银行/yínháng", "最后/zuìhòu 回家/huíjiā 做饭/zuòfàn"],
             "BAC", ["ABC", "BCA", "CAB"], ["然后 can't open the text.", "最后 must come last.", "最后 can't open the text."],
             "**B** 先 → **A** 然后 → **C** 最后.", "After work I go to the bank first, then shopping at the supermarket, and finally home to cook."),
      order3("paixu", ["他/tā 就/jiù 给/gěi 我/wǒ 打/dǎ 了/le 电话/diànhuà", "我/wǒ 刚/gāng 到/dào 家/jiā", "还/hái 没/méi 坐/zuò 下/xià"],
             "BCA", ["ABC", "BAC", "CBA"], ["就 can't open the text.", "还没坐下 belongs to 'me' and comes before the call interrupts.", "还没坐下 needs a subject before it."],
             "**B** 我刚到家，**C** 还没坐下，**A** 他就给我打了电话。", "I'd just got home and hadn't even sat down when he called me."),
      order3("paixu", ["但是/dànshì 他/tā 说/shuō 得/de 非常/fēicháng 好/hǎo", "他/tā 只/zhǐ 学/xué 了/le 半/bàn 年/nián 中文/Zhōngwén", "大家/dàjiā 都/dōu 以为/yǐwéi 他/tā 是/shì 中国人/Zhōngguórén"],
             "BAC", ["ABC", "ACB", "CAB"], ["但是 can't open the text.", "但是 can't open the text.", "C as an opener leaves 但是 contrasting the wrong things."],
             "**B** only half a year **A** but speaks very well **C** so everyone thought he was Chinese.", "He's only studied Chinese for half a year, but he speaks it so well that everyone thought he was Chinese."),
      star("order2", "我/wǒ ＿ ＿ ★ ＿ 。", ["一点儿/yìdiǎnr", "高/gāo", "他/tā", "比/bǐ"], ["高/gāo", "比/bǐ", "他/tā", "一点儿/yìdiǎnr"],
           ["", "比 comes first — slot 1.", "他 follows 比 — slot 2.", "一点儿 follows the adjective — slot 4."],
           "我 **比 他 高 一点儿**。", "I'm a bit taller than him."),
      star("order2", "他/tā ＿ ＿ ★ ＿ 。", ["得/de", "很好/hěn hǎo", "说/shuō", "中文/Zhōngwén"], ["得/de", "中文/Zhōngwén", "说/shuō", "很好/hěn hǎo"],
           ["", "中文 is the topic — slot 1.", "说 comes before 得 — slot 2.", "很好 ends the sentence — slot 4."],
           "他 **中文 说 得 很好**。", "He speaks Chinese very well."),
      star("order2", "我/wǒ ＿ ＿ ★ ＿ 了/le 。", ["书/shū", "那/nà 本/běn", "看完/kàn wán", "已经/yǐjīng"], ["那/nà 本/běn", "已经/yǐjīng", "看完/kàn wán", "书/shū"],
           ["", "已经 comes first — slot 1.", "看完 is the verb — slot 2.", "书 follows 那本 — slot 4."],
           "我 **已经 看完 那本 书** 了。", "I've already finished reading that book."),
      star("order2", "你/nǐ ＿ ＿ ★ ＿ ？", ["没有/méiyǒu", "中国/Zhōngguó", "以前/yǐqián", "去过/qù guo"], ["中国/Zhōngguó", "以前/yǐqián", "去过/qù guo", "没有/méiyǒu"],
           ["", "以前 comes first — slot 1.", "去过 is the verb — slot 2.", "没有 ends the question — slot 4."],
           "你 **以前 去过 中国 没有**？", "Have you ever been to China before?"),
      star("order2", "＿ ＿ ★ ＿ 一边/yìbiān 听/tīng 音乐/yīnyuè 。", ["一边/yìbiān", "跑步/pǎobù", "他/tā", "喜欢/xǐhuan"], ["一边/yìbiān", "他/tā", "喜欢/xǐhuan", "跑步/pǎobù"],
           ["", "他 is the subject — slot 1.", "喜欢 — slot 2.", "跑步 follows 一边 — slot 4."],
           "**他 喜欢 一边 跑步** 一边听音乐。", "He likes listening to music while running."),
      star("order2", "我/wǒ 家/jiā ＿ ＿ ★ ＿ 。", ["远/yuǎn", "不/bú 太/tài", "公司/gōngsī", "离/lí"], ["不/bú 太/tài", "离/lí", "公司/gōngsī", "远/yuǎn"],
           ["", "离 comes first — slot 1.", "公司 follows 离 — slot 2.", "远 ends the sentence — slot 4."],
           "我家 **离 公司 不太 远**。", "My home isn't very far from the office.")])

